mapper.select:
SELECT device_token_id, user_id, fcm_token, device_type, is_active, created_at, updated_at
FROM device_token
WHERE fcm_token = #{fcmToken}

mapper.update:
UPDATE device_token
SET is_active = FALSE
WHERE device_token_id = #{deviceTokenId}
  AND user_id = #{userId}
  AND is_active = TRUE
